package review.mysql;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class IntegrationPolicyTests {
 @Test void defaultEntryCannotConnectOrStart(){MySqlIntegrationServer.main(new String[0]);}
 @Test void trustStoreRejectsEmptyPrivateAndLeafEntries()throws Exception{
  var empty=java.security.KeyStore.getInstance("PKCS12");empty.load(null,null);assertThrows(Exception.class,()->MySqlIntegrationServer.validateTrustStore(empty));
  var store=org.mockito.Mockito.mock(java.security.KeyStore.class);org.mockito.Mockito.when(store.size()).thenReturn(1);org.mockito.Mockito.when(store.aliases()).thenAnswer(i->Collections.enumeration(List.of("synthetic")));var cert=org.mockito.Mockito.mock(java.security.cert.X509Certificate.class);org.mockito.Mockito.when(store.getCertificate("synthetic")).thenReturn(cert);org.mockito.Mockito.when(cert.getBasicConstraints()).thenReturn(-1);assertThrows(Exception.class,()->MySqlIntegrationServer.validateTrustStore(store));org.mockito.Mockito.when(cert.getBasicConstraints()).thenReturn(0);MySqlIntegrationServer.validateTrustStore(store);org.mockito.Mockito.when(store.isKeyEntry("synthetic")).thenReturn(true);assertThrows(Exception.class,()->MySqlIntegrationServer.validateTrustStore(store));
 }
 @Test void wrongActualDatabaseStopsBeforeAnyBusinessMetadataOrWrite()throws Exception{
  String id=UUID.randomUUID().toString();var c=org.mockito.Mockito.mock(java.sql.Connection.class);var meta=org.mockito.Mockito.mock(java.sql.DatabaseMetaData.class);var s=org.mockito.Mockito.mock(java.sql.Statement.class);var r=org.mockito.Mockito.mock(java.sql.ResultSet.class);
  org.mockito.Mockito.when(c.getMetaData()).thenReturn(meta);org.mockito.Mockito.when(meta.getURL()).thenReturn(IntegrationSchema.url(id));org.mockito.Mockito.when(meta.getDriverName()).thenReturn("MySQL Connector/J");org.mockito.Mockito.when(c.createStatement()).thenReturn(s);org.mockito.Mockito.when(s.executeQuery("SELECT DATABASE(),CURRENT_USER(),CURRENT_ROLE(),VERSION()")).thenReturn(r);org.mockito.Mockito.when(r.next()).thenReturn(true);org.mockito.Mockito.when(r.getString(1)).thenReturn("ai_study_planner_test");
  assertThrows(IllegalStateException.class,()->IntegrationSchema.verifyMySql(c,id));org.mockito.Mockito.verify(c,org.mockito.Mockito.never()).prepareStatement(org.mockito.ArgumentMatchers.anyString());org.mockito.Mockito.verify(s,org.mockito.Mockito.never()).executeUpdate(org.mockito.ArgumentMatchers.anyString());
 }
 @Test void identifiersAndGeneratedSqlNeverTargetExistingDatabases()throws Exception{String id=UUID.randomUUID().toString(),schema=IntegrationSchema.name(id);assertTrue(schema.length()<=64);assertTrue(schema.matches("ai_study_planner_integration_[0-9a-f]{32}"));assertThrows(IllegalArgumentException.class,()->IntegrationSchema.name("ai_study_planner_test"));String sql=IntegrationSchema.ddl(id);assertTrue(sql.contains("CREATE DATABASE `"+schema+"`"));assertFalse(sql.contains("IF NOT EXISTS"));assertFalse(sql.contains("DROP "));assertFalse(sql.contains("study_plans"));assertTrue(IntegrationSchema.grants(id).contains("`.`study_saved_plans`"));assertFalse(IntegrationSchema.grants(id).contains(".*"));}
 @Test void privilegeReviewRejectsGlobalRoleDelegationAndOtherSchema()throws Exception{String id=UUID.randomUUID().toString();var grants=new ArrayList<String>();grants.add("GRANT USAGE ON *.* TO 'synthetic'@'localhost'");for(String t:IntegrationSchema.TABLES)grants.add("GRANT SELECT, INSERT, UPDATE ON `"+IntegrationSchema.name(id)+"`.`"+t+"` TO 'synthetic'@'localhost'");IntegrationSchema.grantsSafe(grants,id);for(String bad:List.of("GRANT ALL PRIVILEGES ON *.* TO x","GRANT 'role' TO x","GRANT SELECT ON ai_study_planner_test.* TO x","GRANT PROXY ON x TO y")){var changed=new ArrayList<>(grants);changed.add(bad);assertThrows(Exception.class,()->IntegrationSchema.grantsSafe(changed,id));}}
 @Test void listenerAndNetworkGuardProtectOldPortsAndAllAiHosts(){for(int p:List.of(8080,8083,8084,8085,8086,8099,8101,8102,8103))assertThrows(IllegalArgumentException.class,()->IntegrationSchema.port(p));var g=new MySqlIntegrationServer.Guard(8104,false);assertDoesNotThrow(()->g.checkConnect("127.0.0.1",3307));assertThrows(SecurityException.class,()->g.checkConnect("127.0.0.1",3306));assertTrue(IntegrationSchema.url(UUID.randomUUID().toString()).startsWith("jdbc:mysql://127.0.0.1:3307/"));for(String h:List.of("api.openai.com","generativelanguage.googleapis.com","192.168.1.20","localhost"))assertThrows(SecurityException.class,()->g.checkConnect(h,443));assertThrows(SecurityException.class,()->g.checkListen(8104));assertThrows(SecurityException.class,()->new MySqlIntegrationServer.Guard(8104,true).checkAccept("192.168.1.20",123));}
 @Test void entityMappingsUseActualEightBusinessTables()throws Exception{for(Class<?> type:List.of(ai_study_planner.User.class,ai_study_planner.Goal.class,ai_study_planner.Subject.class,ai_study_planner.StudyLog.class,ai_study_planner.StudyQuestion.class,ai_study_planner.AiResponse.class)){String table=type.getAnnotation(jakarta.persistence.Table.class).name();assertTrue(IntegrationSchema.BUSINESS.contains(table));assertTrue(IntegrationSchema.tablesSql().contains("CREATE TABLE "+table+" "));}assertTrue(IntegrationSchema.tablesSql().contains("UNIQUE KEY uq_saved_goal_date(user_id,goal_id,plan_date)"));assertTrue(IntegrationSchema.tablesSql().contains("FOREIGN KEY(goal_id,user_id)"));}
}
